(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.04+t*0.5)*6+Math.cos((y+w1y)*0.03-t*0.4)*4;
  const w2y = Math.cos((y+w1y)*0.04-t*0.45)*6+Math.sin((x+w1x)*0.035+t*0.55)*4;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const rot = t*0.05, cosR = Math.cos(rot), sinR = Math.sin(rot);
  const rx = (sx-cx)*cosR-(sy-cy)*sinR+cx, ry = (sx-cx)*sinR+(sy-cy)*cosR+cy;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.05],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.07],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.04],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.08],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.06],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.05],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.09],
    [400+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.085,1.8,0.06]
  ];
  let aS=0,iS=0,cS=0;
  for(let j=0;j<8;j++){
    const[sX,sY,f,sp,cf]=src[j],n1=src[(j+1)%8];
    const d=Math.sqrt((rx-sX)**2+(ry-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const dN=Math.sqrt((sX-n1[0])**2+(sY-n1[1])**2);
    cS+=Math.sin(d*cf+dN*0.1-t*sp*0.3)*wave;
  }
  const act=aS/8,inh=iS/8,cross=cS/8;
  const bg=(Math.sin(rx*0.04+ry*0.025+t*0.8)+Math.sin(rx*0.03-ry*0.04+t*1.1))/2+Math.sin((rx+ry)*0.12+t*2.5)*0.2+Math.sin((rx-ry)*0.1-t*2)*0.2+Math.sin(rx*0.08+ry*0.06+t*1.8)*0.15;
  const dist=Math.sqrt((rx-cx)**2+(ry-cy)**2),ang=Math.atan2(ry-cy,rx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.03-ang*5+t*0.8)*0.6)*0.35;
  let rd=act-inh*0.7+bg*0.25+spiral+cross*0.3;
  rd+=Math.sin(rd*2.5+t)*0.15+Math.sin(rd*1.5-t*0.7)*0.1;
  const reaction=Math.tanh(rd*2.0);
  const cell=Math.tanh((Math.sin(rx*0.15)*Math.sin(ry*0.15)+Math.sin((rx+ry)*0.1+t)*0.5+Math.sin(rx*0.22-t*0.3)*Math.sin(ry*0.18+t*0.4)*0.3)*1.5)*0.3;
  const pulse=Math.sin(dist*0.02-t*0.8)*0.15*Math.exp(-dist*0.005);
  const blend=reaction*0.6+cell*0.25+pulse*0.15,v=blend*0.5+0.5;
  const pal=[[6,12,52],[10,55,85],[15,110,120],[25,155,135],[180,175,45],[215,135,50],[205,90,65],[165,50,75],[100,25,60],[45,15,55],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,edge=Math.abs(reaction)>0.65?1.12:1.0,glow=Math.max(0,reaction)*0.08;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*200)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*150)|0)
  ];
}
